      expect(await res.json()).toMatchObject({ id: "update-1", data: { user: 2 } });
      const written = cookieValue(res.headers.getSetCookie().find((c) => c.startsWith("h3-test="))!);
      expect(await unseal(written, newPassword, sealDefaults)).toMatchObject({
        id: "update-1",
        data: { user: 2 },
      });
      await expect(unseal(written, oldPassword, sealDefaults)).rejects.toThrow("Bad hmac value");
    });

    it("throws for a too short extra password, with or without cookie", async () => {
      const config: SessionConfig = { ...rotatedConfig, extraUnsealPasswords: ["curta"] };
      t.app.get("/short-get", async (event) => {
        try {
          await getSession(event, config);
          return { error: null };
        } catch (error) {
          return { error: (error as Error).message };
        }
      });
      t.app.get("/short-use", async (event) => {
        try {
          await useSession(event, config);
          return { error: null };
        } catch (error) {
          return { error: (error as Error).message };
        }
      });
      const sealed = await sealedWith(oldPassword, {
        id: "short-1",
        createdAt: Date.now(),
        data: { user: 1 },
      });
      for (const path of ["/short-get", "/short-use"]) {
        for (const headers of [{}, { Cookie: `h3-test=${sealed}` }]) {
          const res = await t.fetch(path, { headers });
          expect((await res.json()).error).toContain("too short");
        }
      }
    });

    it("validates extras against the stricter of the two minimums", async () => {
      // 34 characters: enough for encryption (32), too short for integrity (40)
      const midPassword = "mid-password-0123456789abcdefghijk";
      const config: SessionConfig = {
        name: "h3-test",
        password: "p".repeat(45),
        extraUnsealPasswords: [midPassword],
        seal: { ...sealDefaults, integrity: { ...sealDefaults.integrity, minPasswordlength: 40 } },
