      t.app.get("/mid", async (event) => {
        try {
          await useSession(event, config);
          return { error: null };
        } catch (error) {
          return { error: (error as Error).message };
        }
      });
      const res = await t.fetch("/mid");
      expect((await res.json()).error).toContain("too short");
    });

    it("opens legacy session sealed with an extra password and reseals it", async () => {
      readRoute("/legacy", rotatedConfig);
      const legacy = await legacySealedWith(oldPassword, {
        id: "legacy-1",
        createdAt: Date.now(),
        data: { user: 1 },
      });
      const res = await t.fetch("/legacy", { headers: { Cookie: `h3-test=${legacy}` } });
      expect(await res.json()).toMatchObject({ id: "legacy-1", data: { user: 1 } });
      const setCookie = res.headers.getSetCookie().find((c) => c.startsWith("h3-test="));
      expect(setCookie).toBeDefined();
      expect(await unseal(cookieValue(setCookie!), newPassword, sealDefaults)).toMatchObject({
        id: "legacy-1",
      });
    });

    it("does not open legacy extra-sealed session with legacySealFallback: false", async () => {
      readRoute("/legacy-off", { ...rotatedConfig, legacySealFallback: false });
      const legacy = await legacySealedWith(oldPassword, {
        id: "legacy-off-1",
        createdAt: Date.now(),
        data: { user: 1 },
      });
      const res = await t.fetch("/legacy-off", { headers: { Cookie: `h3-test=${legacy}` } });
      const body = await res.json();
      expect(body.id).not.toBe("legacy-off-1");
      expect(body.data).toEqual({});
    });
  });
});

