        return { id: session.id };
      });

      const res1 = await t.fetch("/stable");
      const setCookie = res1.headers.getSetCookie()[0];
      const { id } = await res1.json();

      const res2 = await t.fetch("/stable", {
        headers: { Cookie: setCookie.split(";")[0] },
      });
      expect(await res2.json()).toMatchObject({ id });
    });
  });

  describe("extraUnsealPasswords", () => {
    const oldPassword = "old-password-0123456789abcdefghijklmn";
    const newPassword = "new-password-0123456789abcdefghijklmn";
    const unlistedPassword = "unlisted-password-0123456789abcdefgh";
    const rotatedConfig: SessionConfig = {
      name: "h3-test",
      password: newPassword,
      extraUnsealPasswords: [oldPassword],
    };

    const readRoute = (path: string, config: SessionConfig) =>
      t.app.get(path, async (event) => {
        const session = await getSession(event, config);
        return { id: session.id, data: session.data };
      });

    const sealedWith = (password: string, session: object) => seal(session, password, sealDefaults);

    const legacySealedWith = (password: string, session: object) =>
      seal(session, password, {
        ...sealDefaults,
        encryption: { ...sealDefaults.encryption, iterations: 1 },
        integrity: { ...sealDefaults.integrity, iterations: 1 },
      });

    // Value of the `h3-test` cookie in a `Set-Cookie` header
    const cookieValue = (setCookie: string) =>
      decodeURIComponent(setCookie.split(";")[0].slice("h3-test=".length));

    it("opens with password without trying extras", async () => {
      readRoute("/primary", rotatedConfig);
      const sealed = await sealedWith(newPassword, {
        id: "primary-1",
        createdAt: Date.now(),
        data: { user: 1 },
      });
      const deriveBits = vi.spyOn(crypto.subtle, "deriveBits");
      const res = await t.fetch("/primary", { headers: { Cookie: `h3-test=${sealed}` } });
      expect(await res.json()).toMatchObject({ id: "primary-1", data: { user: 1 } });
      // Integrity and encryption derivations, only for the primary password
      expect(deriveBits).toHaveBeenCalledTimes(2);
      deriveBits.mockRestore();
    });

    it("tries extras in order and stops at the first match", async () => {
      readRoute("/order", {
        ...rotatedConfig,
        extraUnsealPasswords: [unlistedPassword, oldPassword],
        legacySealFallback: false,
      });
      const sealed = await sealedWith(oldPassword, {
        id: "order-1",
        createdAt: Date.now(),
        data: { user: 2 },
      });
      const deriveBits = vi.spyOn(crypto.subtle, "deriveBits");
      // Header read: no reseal, so only the unseal attempts derive keys
      const res = await t.fetch("/order", { headers: { "x-h3-test-session": sealed } });
      expect(await res.json()).toMatchObject({ id: "order-1", data: { user: 2 } });
      // Primary and first extra fail HMAC (1 derivation each), the second opens (2)
      expect(deriveBits).toHaveBeenCalledTimes(4);
      deriveBits.mockRestore();
    });

    it("opens session sealed with an extra password (cookie and header)", async () => {
      readRoute("/extra", rotatedConfig);
      const sealed = await sealedWith(oldPassword, {
        id: "extra-1",
        createdAt: Date.now(),
        data: { user: 1 },
      });
      for (const headers of [{ Cookie: `h3-test=${sealed}` }, { "x-h3-test-session": sealed }]) {
        const res = await t.fetch("/extra", { headers });
        expect(await res.json()).toMatchObject({ id: "extra-1", data: { user: 1 } });
      }
    });

    it("ignores session sealed with an unlisted password", async () => {
      readRoute("/unlisted", rotatedConfig);
      const sealed = await sealedWith(unlistedPassword, {
        id: "unlisted-1",
        createdAt: Date.now(),
        data: { user: 1 },
      });
      const res = await t.fetch("/unlisted", { headers: { Cookie: `h3-test=${sealed}` } });
      const body = await res.json();
      expect(body.id).not.toBe("unlisted-1");
      expect(body.data).toEqual({});
    });

    it("rejects expired session opened by an extra password", async () => {
      readRoute("/expired", { ...rotatedConfig, maxAge: 60 });
      const sealed = await sealedWith(oldPassword, {
        id: "expired-1",
        createdAt: Date.now() - 120_000,
        data: { user: 1 },
      });
      const res = await t.fetch("/expired", { headers: { Cookie: `h3-test=${sealed}` } });
      const body = await res.json();
      expect(body.id).not.toBe("expired-1");
      expect(body.data).toEqual({});
    });

    it("reseals cookie session opened by an extra password", async () => {
      readRoute("/reseal", rotatedConfig);
      const sealed = await sealedWith(oldPassword, {
        id: "reseal-1",
        createdAt: Date.now(),
        data: { user: 1 },
      });
      const res = await t.fetch("/reseal", { headers: { Cookie: `h3-test=${sealed}` } });
      expect(await res.json()).toMatchObject({ id: "reseal-1" });
      const setCookie = res.headers.getSetCookie().find((c) => c.startsWith("h3-test="));
      expect(setCookie).toBeDefined();
      // The rewritten cookie opens with the current password alone
      expect(await unseal(cookieValue(setCookie!), newPassword, sealDefaults)).toMatchObject({
        id: "reseal-1",
        data: { user: 1 },
      });
    });

    it("does not reseal cookie session sealed with the current password", async () => {
      readRoute("/current", rotatedConfig);
      const sealed = await sealedWith(newPassword, {
        id: "current-1",
        createdAt: Date.now(),
        data: { user: 1 },
      });
      const res = await t.fetch("/current", { headers: { Cookie: `h3-test=${sealed}` } });
      expect(await res.json()).toMatchObject({ id: "current-1" });
      expect(res.headers.getSetCookie()).toHaveLength(0);
    });

    it("does not reseal header session opened by an extra password", async () => {
      readRoute("/header", rotatedConfig);
      const sealed = await sealedWith(oldPassword, {
        id: "header-1",
        createdAt: Date.now(),
        data: { user: 1 },
      });
      const first = await t.fetch("/header", { headers: { "x-h3-test-session": sealed } });
      expect(await first.json()).toMatchObject({ id: "header-1" });
      expect(first.headers.getSetCookie()).toHaveLength(0);
      // Still opens while the old password is listed
      const second = await t.fetch("/header", { headers: { "x-h3-test-session": sealed } });
      expect(await second.json()).toMatchObject({ id: "header-1" });
    });

    it("seals with password only after opening with an extra", async () => {
      t.app.post("/rotated-update", async (event) => {
        await getSession(event, rotatedConfig);
        const session = await updateSession(event, rotatedConfig, { user: 2 });
        return { id: session.id, data: session.data };
      });
      const sealed = await sealedWith(oldPassword, {
        id: "update-1",
        createdAt: Date.now(),
        data: { user: 1 },
      });
      const res = await t.fetch("/rotated-update", {
        method: "POST",
        headers: { Cookie: `h3-test=${sealed}` },
      });
      expect(await res.json()).toMatchObject({ id: "update-1", data: { user: 2 } });
      const written = cookieValue(res.headers.getSetCookie().find((c) => c.startsWith("h3-test="))!);
      expect(await unseal(written, newPassword, sealDefaults)).toMatchObject({
        id: "update-1",
        data: { user: 2 },
      });
      await expect(unseal(written, oldPassword, sealDefaults)).rejects.toThrow("Bad hmac value");
    });

    it("throws for a too short extra password, with or without cookie", async () => {
      const config: SessionConfig = { ...rotatedConfig, extraUnsealPasswords: ["curta"] };
      t.app.get("/short-get", async (event) => {
        try {
          await getSession(event, config);
          return { error: null };
        } catch (error) {
          return { error: (error as Error).message };
        }
      });
      t.app.get("/short-use", async (event) => {
        try {
          await useSession(event, config);
          return { error: null };
        } catch (error) {
          return { error: (error as Error).message };
        }
      });
      const sealed = await sealedWith(oldPassword, {
        id: "short-1",
        createdAt: Date.now(),
        data: { user: 1 },
      });
      for (const path of ["/short-get", "/short-use"]) {
        for (const headers of [{}, { Cookie: `h3-test=${sealed}` }]) {
          const res = await t.fetch(path, { headers });
          expect((await res.json()).error).toContain("too short");
        }
      }
    });

    it("validates extras against the stricter of the two minimums", async () => {
      // 34 characters: enough for encryption (32), too short for integrity (40)
      const midPassword = "mid-password-0123456789abcdefghijk";
      const config: SessionConfig = {
        name: "h3-test",
        password: "p".repeat(45),
        extraUnsealPasswords: [midPassword],
        seal: { ...sealDefaults, integrity: { ...sealDefaults.integrity, minPasswordlength: 40 } },
      };
      t.app.get("/mid", async (event) => {
        try {
          await useSession(event, config);
          return { error: null };
        } catch (error) {
          return { error: (error as Error).message };
        }
      });
      const res = await t.fetch("/mid");
      expect((await res.json()).error).toContain("too short");
    });

    it("opens legacy session sealed with an extra password and reseals it", async () => {
      readRoute("/legacy", rotatedConfig);
      const legacy = await legacySealedWith(oldPassword, {
        id: "legacy-1",
        createdAt: Date.now(),
        data: { user: 1 },
      });
      const res = await t.fetch("/legacy", { headers: { Cookie: `h3-test=${legacy}` } });
      expect(await res.json()).toMatchObject({ id: "legacy-1", data: { user: 1 } });
      const setCookie = res.headers.getSetCookie().find((c) => c.startsWith("h3-test="));
      expect(setCookie).toBeDefined();
      expect(await unseal(cookieValue(setCookie!), newPassword, sealDefaults)).toMatchObject({
        id: "legacy-1",
      });
    });

    it("does not open legacy extra-sealed session with legacySealFallback: false", async () => {
      readRoute("/legacy-off", { ...rotatedConfig, legacySealFallback: false });
      const legacy = await legacySealedWith(oldPassword, {
        id: "legacy-off-1",
        createdAt: Date.now(),
        data: { user: 1 },
      });
      const res = await t.fetch("/legacy-off", { headers: { Cookie: `h3-test=${legacy}` } });
      const body = await res.json();
      expect(body.id).not.toBe("legacy-off-1");
      expect(body.data).toEqual({});
    });
  });
});

import type { SessionConfig } from "../src/utils/session.ts";
import { beforeEach, describe, vi } from "vitest";
import {
  useSession,
  getSession,
  updateSession,
  clearSession,
  readBody,
  H3,
  HTTPError,
} from "../src/index.ts";
import { seal, unseal, defaults as sealDefaults } from "../src/utils/internal/iron-crypto.ts";
import { describeMatrix } from "./_setup.ts";

describeMatrix("session", (t, { it, expect }) => {
  let app: H3;

  let cookie = "";

  let sessionIdCtr = 0;
  const sessionConfig: SessionConfig = {
    name: "h3-test",
    password: "1234567123456712345671234567123456712345671234567",
    generateId: () => ++sessionIdCtr + "",
  };

  beforeEach(() => {
    app = new H3({});
    t.app.all("/", async (event) => {
      const session = await useSession(event, sessionConfig);
      if (event.req.method === "POST") {
        await session.update((await readBody(event)) as any);
      }
      return { session };
    });
    t.app.use(app.handler);
  });

  it("initiates session", async () => {
    const result = await t.fetch("/");
    expect(result.headers.getSetCookie()).toHaveLength(1);
    cookie = result.headers.getSetCookie()[0];
    expect(await result.json()).toMatchObject({
      session: { id: "1", data: {} },
    });
  });

  it("sets SameSite=Lax by default", async () => {
    const result = await t.fetch("/");
    expect(result.headers.getSetCookie()[0]).toContain("SameSite=Lax");
  });

  it("allows overriding SameSite via config.cookie", async () => {
    t.app.get("/strict", async (event) => {
      const session = await useSession(event, {
        ...sessionConfig,
        cookie: { sameSite: "strict" },
      });
      return { session };
    });
    const strict = await t.fetch("/strict");
    expect(strict.headers.getSetCookie()[0]).toContain("SameSite=Strict");

    t.app.get("/none", async (event) => {
      const session = await useSession(event, {
        ...sessionConfig,
        cookie: { sameSite: false },
      });
      return { session };
    });
    const none = await t.fetch("/none");
    expect(none.headers.getSetCookie()[0]).not.toContain("SameSite");
  });

  it("gets same session back", async () => {
    const result = await t.fetch("/", { headers: { Cookie: cookie } });
    expect(await result.json()).toMatchObject({
      session: { id: "1", data: {} },
    });
  });

  it("set session data", async () => {
    const result = await t.fetch("/", {
      method: "POST",
      headers: { Cookie: cookie },
      body: JSON.stringify({ foo: "bar" }),
    });
    cookie = result.headers.getSetCookie()[0];
    expect(await result.json()).toMatchObject({
      session: { id: "1", data: { foo: "bar" } },
    });

    const result2 = await t.fetch("/", { headers: { Cookie: cookie } });
    expect(await result2.json()).toMatchObject({
      session: { id: "1", data: { foo: "bar" } },
    });
  });

  it("gets same session back (concurrent)", async () => {
    app.get("/concurrent", async (event) => {
      const sessions = await Promise.all(
        [1, 2, 3].map(() =>
          useSession(event, sessionConfig).then((s) => ({
            id: s.id,
            data: s.data,
          })),
        ),
      );
      return {
        sessions,
      };
    });
    const result = await t.fetch("/concurrent", {
      headers: { Cookie: cookie },
    });
    expect(await result.json()).toMatchObject({
      sessions: [1, 2, 3].map(() => ({ id: "1", data: { foo: "bar" } })),
    });
  });

  it("clearSession sets maxAge=0 to delete cookie", async () => {
    t.app.get("/clear", async (event) => {
      await clearSession(event, sessionConfig);
      return { cleared: true };
    });
    const res = await t.fetch("/clear", {
      headers: { Cookie: cookie },
    });
    const cookies = res.headers.getSetCookie();
    expect(cookies.length).toBeGreaterThanOrEqual(1);
    expect(cookies[0]).toContain("Max-Age=0");
  });

  it("unseals and reseals legacy sessions sealed with iterations: 1", async () => {
    const legacySealed = await seal(
      { id: "legacy", createdAt: Date.now(), data: { foo: "legacy" } },
      sessionConfig.password,
      {
        ...sealDefaults,
        encryption: { ...sealDefaults.encryption, iterations: 1 },
        integrity: { ...sealDefaults.integrity, iterations: 1 },
      },
    );

    const result = await t.fetch("/", {
      headers: { Cookie: `h3-test=${legacySealed}` },
    });
    expect(await result.json()).toMatchObject({
      session: { id: "legacy", data: { foo: "legacy" } },
    });

    // Legacy cookie is transparently resealed with the current default
    const setCookies = result.headers.getSetCookie();
    expect(setCookies).toHaveLength(1);
    const resealed = decodeURIComponent(setCookies[0].match(/h3-test=([^;]+)/)![1]);
    expect(
      await unseal(resealed, sessionConfig.password, sealDefaults), // current iterations, no fallback
    ).toMatchObject({ id: "legacy", data: { foo: "legacy" } });
  });

  it("rejects legacy sessions with legacySealFallback: false", async () => {
    const legacySealed = await seal(
      { id: "legacy", createdAt: Date.now(), data: { foo: "legacy" } },
      sessionConfig.password,
      {
        ...sealDefaults,
        encryption: { ...sealDefaults.encryption, iterations: 1 },
        integrity: { ...sealDefaults.integrity, iterations: 1 },
      },
    );

    t.app.all("/strict", async (event) => {
      const session = await useSession(event, {
        ...sessionConfig,
        legacySealFallback: false,
      });
      return { session };
    });

    const result = await t.fetch("/strict", {
      headers: { Cookie: `h3-test=${legacySealed}` },
    });
    const body = await result.json();
    expect(body.session.id).not.toBe("legacy");
    expect(body.session.data).toEqual({});
  });

  it("idleTimeout slides expiration for active sessions", async () => {
    const t0 = Date.parse("2030-01-01T00:00:00Z");
    vi.useFakeTimers({ toFake: ["Date"], now: t0 });
    try {
      let idCtr = 0;
      const config: SessionConfig = {
        name: "h3-idle",
        password: sessionConfig.password,
        idleTimeout: 60,
        generateId: () => `idle-${++idCtr}`,
      };
      t.app.get("/idle", async (event) => {
        const session = await useSession(event, config);
        await session.update((data) => ({ hits: (data.hits || 0) + 1 }));
        return { id: session.id, data: session.data };
      });
      const idleCookie = (res: Response) =>
        res.headers.getSetCookie().find((c) => c.startsWith("h3-idle="));

      // t=0: new session
      const res1 = await t.fetch("/idle");
      expect((await res1.json()).id).toBe("idle-1");
      let cookie = idleCookie(res1)!;

      // t=45s: active request keeps the session and slides the cookie expiry
      vi.setSystemTime(t0 + 45_000);
      const res2 = await t.fetch("/idle", { headers: { Cookie: cookie } });
      expect(await res2.json()).toMatchObject({ id: "idle-1", data: { hits: 2 } });
      const resealed = idleCookie(res2);
      expect(resealed).toBeDefined();
      expect(resealed).toContain(`Expires=${new Date(t0 + 45_000 + 60_000).toUTCString()}`);
      cookie = resealed!;

      // t=90s: past createdAt + idleTimeout, but only 45s idle — the session and
      // its data survive the reseals
      vi.setSystemTime(t0 + 90_000);
      const res3 = await t.fetch("/idle", { headers: { Cookie: cookie } });
      expect(await res3.json()).toMatchObject({ id: "idle-1", data: { hits: 3 } });
    } finally {
      vi.useRealTimers();
    }
  });

  it("idleTimeout expires sessions after exactly idleTimeout of inactivity", async () => {
    const t0 = Date.parse("2030-01-01T00:00:00Z");
    vi.useFakeTimers({ toFake: ["Date"], now: t0 });
    try {
      let idCtr = 0;
      const config: SessionConfig = {
        name: "h3-idle-exp",
        password: sessionConfig.password,
        idleTimeout: 60,
        generateId: () => `exp-${++idCtr}`,
      };
      t.app.get("/idle-expiry", async (event) => {
        const session = await useSession(event, config);
        return { id: session.id };
      });

      const res1 = await t.fetch("/idle-expiry");
      expect((await res1.json()).id).toBe("exp-1");
      const cookie = res1.headers.getSetCookie().find((c) => c.startsWith("h3-idle-exp="))!;

      // No clock-skew slack: still alive at 59s of inactivity
      vi.setSystemTime(t0 + 59_000);
      const res2 = await t.fetch("/idle-expiry", { headers: { Cookie: cookie } });
      expect((await res2.json()).id).toBe("exp-1");

      // ...and reset at 61s, measured from the original cookie's reseal time
      vi.setSystemTime(t0 + 61_000);
      const res3 = await t.fetch("/idle-expiry", { headers: { Cookie: cookie } });
      expect((await res3.json()).id).toBe("exp-2");
    } finally {
      vi.useRealTimers();
    }
  });

  it("maxAge caps a sliding session", async () => {
    const t0 = Date.parse("2030-01-01T00:00:00Z");
    vi.useFakeTimers({ toFake: ["Date"], now: t0 });
    try {
      let idCtr = 0;
      const config: SessionConfig = {
        name: "h3-both",
        password: sessionConfig.password,
        maxAge: 120,
        idleTimeout: 60,
        generateId: () => `both-${++idCtr}`,
      };
      t.app.get("/both", async (event) => {
        const session = await useSession(event, config);
        return { id: session.id };
      });
      const bothCookie = (res: Response) =>
        res.headers.getSetCookie().find((c) => c.startsWith("h3-both="))!;

      const res1 = await t.fetch("/both");
      expect((await res1.json()).id).toBe("both-1");
      let cookie = bothCookie(res1);

      // t=45s: idle window (t+60s) runs out before the absolute cap (t0+120s)
      vi.setSystemTime(t0 + 45_000);
      const res2 = await t.fetch("/both", { headers: { Cookie: cookie } });
      expect((await res2.json()).id).toBe("both-1");
      cookie = bothCookie(res2);
      expect(cookie).toContain(`Expires=${new Date(t0 + 105_000).toUTCString()}`);

      // t=90s: now the absolute cap is the earlier of the two, so it wins
      vi.setSystemTime(t0 + 90_000);
      const res3 = await t.fetch("/both", { headers: { Cookie: cookie } });
      expect((await res3.json()).id).toBe("both-1");
      cookie = bothCookie(res3);
      expect(cookie).toContain(`Expires=${new Date(t0 + 120_000).toUTCString()}`);

      // t=121s: only 31s idle, but past createdAt + maxAge — session resets
      vi.setSystemTime(t0 + 121_000);
      const res4 = await t.fetch("/both", { headers: { Cookie: cookie } });
      expect((await res4.json()).id).toBe("both-2");
    } finally {
      vi.useRealTimers();
    }
  });

  it("idleTimeout keeps hard expiration for header-carried sessions", async () => {
    const t0 = Date.parse("2030-01-01T00:00:00Z");
    vi.useFakeTimers({ toFake: ["Date"], now: t0 });
    try {
      let idCtr = 0;
      const config: SessionConfig = {
        name: "h3-idleh",
        password: sessionConfig.password,
        idleTimeout: 60,
        generateId: () => `idleh-${++idCtr}`,
      };
      t.app.get("/idle-header", async (event) => {
        const session = await useSession(event, config);
        return { id: session.id };
      });

      const res1 = await t.fetch("/idle-header");
      expect((await res1.json()).id).toBe("idleh-1");
      const setCookie = res1.headers.getSetCookie().find((c) => c.startsWith("h3-idleh="))!;
      const sealed = decodeURIComponent(setCookie.match(/h3-idleh=([^;]+)/)![1]);

      // t=90s: header seals are never resealed, so their `lastSeenAt` stays
      // pinned to when the seal was issued and the window cannot slide
      vi.setSystemTime(t0 + 90_000);
      const res2 = await t.fetch("/idle-header", {
        headers: { "x-h3-idleh-session": sealed },
      });
      expect((await res2.json()).id).toBe("idleh-2");
    } finally {
      vi.useRealTimers();
    }
  });

  it("idleTimeout expiration does not depend on the seal ttl", async () => {
    const t0 = Date.parse("2030-01-01T00:00:00Z");
    vi.useFakeTimers({ toFake: ["Date"], now: t0 });
    try {
      let idCtr = 0;
      const config: SessionConfig = {
        name: "h3-idle-seal",
        password: sessionConfig.password,
        idleTimeout: 60,
        generateId: () => `seal-${++idCtr}`,
        // `SealOptions` has no optional fields, so any override carries a `ttl`.
        // Expiration must not rely on it
        seal: { ...sealDefaults, ttl: 0 },
      };
      t.app.get("/idle-seal", async (event) => {
        const session = await useSession(event, config);
        return { id: session.id };
      });

      const res1 = await t.fetch("/idle-seal");
      expect((await res1.json()).id).toBe("seal-1");
      const cookie = res1.headers.getSetCookie().find((c) => c.startsWith("h3-idle-seal="))!;

      vi.setSystemTime(t0 + 61_000);
      const res2 = await t.fetch("/idle-seal", { headers: { Cookie: cookie } });
      expect((await res2.json()).id).toBe("seal-2");
    } finally {
      vi.useRealTimers();
    }
  });

  it("expires at createdAt + maxAge by default (no idleTimeout)", async () => {
    const t0 = Date.parse("2030-01-01T00:00:00Z");
    vi.useFakeTimers({ toFake: ["Date"], now: t0 });
    try {
      let idCtr = 0;
      const config: SessionConfig = {
